//! Rust source writer for the generated tables.
use std::fmt::{Display, Write};

pub struct Output {
    text: String,
}

impl Output {
    pub fn new() -> Self {
        Self {
            text: String::from(
                "// @generated by crates/apac-core/build/main.rs from data/*.json.\n",
            ),
        }
    }

    /// Verbatim Rust items, for small struct initializers.
    pub fn raw(&mut self, item: &str) {
        self.text.push_str(item);
        self.text.push('\n');
    }

    /// Marks the next item as compiled only into test builds.
    pub fn test_only(&mut self) {
        self.text.push_str("#[cfg(test)]\n");
    }

    /// `static NAME: [TYPE; N] = [...]`, wrapping long rows. Returns `NAME`.
    pub fn array<T: Display>(
        &mut self,
        public: bool,
        name: &str,
        ty: &str,
        items: impl IntoIterator<Item = T>,
    ) -> String {
        let items: Vec<String> = items.into_iter().map(|v| v.to_string()).collect();
        let visibility = if public { "pub " } else { "" };
        let _ = write!(
            self.text,
            "{visibility}static {name}: [{ty}; {}] = [",
            items.len()
        );
        for (i, item) in items.iter().enumerate() {
            if i % 12 == 0 {
                self.text.push_str("\n    ");
            } else {
                self.text.push(' ');
            }
            self.text.push_str(item);
            self.text.push(',');
        }
        self.text.push_str("\n];\n");
        name.to_owned()
    }

    pub fn str_const(&mut self, name: &str, value: &str) {
        let _ = writeln!(self.text, "pub const {name}: &str = {value:?};");
    }

    pub fn finish(self, path: &std::path::Path) {
        std::fs::write(path, self.text).expect("write generated tables");
    }
}

pub fn f64_bits(bits: u64) -> String {
    format!("f64::from_bits(0x{bits:016x})")
}

pub fn pair<T: Display>(values: [T; 2]) -> String {
    format!("[{}, {}]", values[0], values[1])
}

pub fn node(node: [u16; 3]) -> String {
    format!("[{}, {}, {}]", node[0], node[1], node[2])
}
